const challenges=[
{id:'coach',name:'Change of Coach',short:'The coach swap',category:'MOVE TOGETHER',icon:'yoga',color:'#81986b',description:'A yoga session. A new coach. A little less flexibility than expected.',mission:'She takes the lead for a yoga session together. Follow her flow, laugh at the wobbles, and finish with your best joint pose. No flexibility requirements.',reward:'Your friends take on the same poses, with a wedding wish between the wobbles.',extra:'A personalised yoga-coach certificate.',video:'',gift:''},
{id:'marathon',name:'The Married Marathon',short:'Marathon team',category:'THE BIG ONE',icon:'flag',color:'#df6a3b',description:'Your next starting line, now with a teammate for life.',mission:'Take on the marathon you’ve signed up for, each at your own pace. Celebrate the whole adventure together. Plans changed? Another shared milestone counts, too.',reward:'Your virtual finish-line crew: cheers and personal messages from friends and family.',extra:'A post-race treat and a race-day photo keepsake.',video:'',gift:''},
{id:'picnic',name:'Two Countries, One Picnic',short:'The good life',category:'AT × ES',icon:'basket',color:'#bd9655',description:'A taste of Austria. A taste of Spain. A spot just for two.',mission:'Pack an Austrian–Spanish picnic and find somewhere lovely to eat it. Each bring something the other isn’t expecting.',reward:'Family stories from both countries, with a few childhood photos you might wish we hadn’t found.',extra:'A family recipe from each side of the table.',video:'',gift:''},
{id:'sunrise',name:'Before the World Wakes',short:'Early birds',category:'OUTSIDE TOGETHER',icon:'sun',color:'#ca9146',description:'Find a sunrise worth getting out of bed for. Coffee encouraged.',mission:'Watch the sunrise together. Mountain, beach or balcony: every viewpoint counts. Bring a warm drink and take a moment just for yourselves.',reward:'A quiet moment with messages from your closest friends, sharing favourite memories and wishes for your next chapter.',extra:'A letter from your support crew to keep.',video:'',gift:''},
{id:'friendship',name:'The Friendship Checkpoint',short:'The reunion',category:'YOUR PEOPLE',icon:'pin',color:'#678c83',description:'Good company is an excellent reason to take a detour.',mission:'Meet up with the friends behind this gift. Share a meal, head outside, or make a day of it. The checkpoint is wherever we’re together.',reward:'A personal video invitation from your friends, revealing your next get-together.',extra:'An experience to enjoy with your support crew.',video:'',gift:''},
{id:'rest',name:'Rest-Day Champions',short:'Recovery club',category:'RECOVERY COUNTS',icon:'moon',color:'#8690a1',description:'No training. No chores. An outstanding performance in doing nothing.',mission:'Spend an afternoon with no training, no chores and absolutely no productivity goals. Your only assignment is to enjoy doing nothing together.',reward:'Your friends present a very serious sports documentary about your very unremarkable afternoon.',extra:'A film-night or takeaway treat.',video:'',gift:''},
{id:'crew',name:'A Little Help from the Crew',short:'Stronger together',category:'BRING A FRIEND',icon:'people',color:'#658363',description:'Bring your people along. Every great team has a support crew.',mission:'Invite one or more friends to join a run, walk, yoga session or day on the water. Pick an activity and pace that everyone can enjoy.',reward:'Sincere and questionable marriage advice from your crew, plus a reminder that you can always count on them.',extra:'Personal promises of help and time together from friends.',video:'',gift:''}
];
const paths={heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',yoga:'<circle cx="12" cy="4" r="2"/><path d="m4 12 5-4h6l5 4M12 8v7m-6 5 6-5 6 5M3 20h18"/>',flag:'<path d="M4 22V3m0 1c6-5 10 5 16 0v10c-6 5-10-5-16 0"/>',basket:'<path d="m3 10 3 11h12l3-11ZM2 10h20M7 10l5-8 5 8M9 14v3m6-3v3"/>',sun:'<path d="M2 18h20M5 14a7 7 0 0 1 14 0M12 2v2M3 6l2 2m14 0 2-2M2 22h20"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',moon:'<path d="M21 12.8A9 9 0 0 1 11.2 3 9 9 0 1 0 21 12.8Z"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>'};
function badge(icon,color,locked=false){return `<span class="badge ${locked?'locked':''}"><svg viewBox="0 0 100 115" aria-hidden="true"><path d="M50 3 93 27v53l-43 30L7 80V27Z" fill="${color}"/><path d="M50 10 86 31v45l-36 26-36-26V31Z" fill="none" stroke="white" stroke-opacity=".5"/><path d="m30 87 20 12 20-12" fill="none" stroke="white" stroke-opacity=".5"/><g transform="translate(30 32) scale(1.65)" fill="none" stroke="white" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${paths[icon]}</g><circle cx="50" cy="20" r="2" fill="white"/></svg></span>`}
let completed=new Set();let storageAvailable=true;try{const saved=JSON.parse(localStorage.getItem('ultra-of-us-v1')||'[]');if(Array.isArray(saved))completed=new Set(saved.filter(id=>challenges.some(c=>c.id===id)))}catch{storageAvailable=false}
const dialog=document.getElementById('detail');let currentId=null;
function persist(){try{localStorage.setItem('ultra-of-us-v1',JSON.stringify([...completed]))}catch{storageAvailable=false;document.querySelector('footer>span:last-child').textContent='Progress lasts for this visit only.'}}
function render(){const count=completed.size;document.getElementById('nav-count').textContent=`${count+1} / 8`;document.getElementById('done-count').innerHTML=`${count}<span> / 7</span>`;document.getElementById('collection-count').textContent=`${count+1} earned · ${7-count} waiting for a story`;document.getElementById('marriage-badge').innerHTML=badge('heart','#e94919');document.getElementById('cards').innerHTML=challenges.map((c,i)=>`<button class="card ${completed.has(c.id)?'earned':''}" data-id="${c.id}" aria-label="${c.name}${completed.has(c.id)?', completed':''}"><span class="card-top">${badge(c.icon,c.color)}<span class="tag">${completed.has(c.id)?'✓ COMPLETED':String(i+1).padStart(2,'0')+' / 07'}</span></span><h3>${c.name}</h3><p>${c.description}</p><span class="card-bottom"><span>${completed.has(c.id)?'Badge earned · View reward':'Video message + a little extra'}</span><b>↗</b></span></button>`).join('')+'<div class="note-card"><span class="note-icon">∞</span><h3>No finish time.<br>No wrong turns.</h3><p>Just a few good excuses to make memories together.</p></div>';document.getElementById('badges').innerHTML=`<button class="badge-item" data-id="marriage">${badge('heart','#e94919')}<span>Officially a team</span><small>✓ EARNED</small></button>`+challenges.map(c=>`<button class="badge-item" data-id="${c.id}">${badge(c.icon,c.color,!completed.has(c.id))}<span>${c.short}</span><small>${completed.has(c.id)?'✓ EARNED':'LOCKED'}</small></button>`).join('');renderProfile();document.querySelectorAll('[data-id]').forEach(b=>b.addEventListener('click',()=>openDetail(b.dataset.id)))}
function renderProfile(){const points=[[24,116],[175,90],[325,30],[475,75],[625,42],[775,84],[925,112],[1075,57]];const route='M24 116 80 109 125 116 175 90 215 96 266 54 290 66 325 30 355 63 392 56 430 84 475 75 521 91 566 64 598 73 625 42 665 71 696 62 735 87 775 84 823 103 860 95 895 111 925 112 966 91 1006 99 1041 70 1075 57';document.getElementById('profile').innerHTML=`<svg viewBox="0 0 1100 145" preserveAspectRatio="none" aria-label="Illustrative elevation profile with eight adventure checkpoints"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#adc08b" stop-opacity=".35"/><stop offset="1" stop-color="#adc08b" stop-opacity=".04"/></linearGradient></defs><path d="M0 45H1100M0 90H1100M0 135H1100" stroke="#ffffff" opacity=".09" stroke-dasharray="3 5"/><path d="${route} V145H24Z" fill="url(#fill)"/><path d="${route}" fill="none" stroke="#bdd09b" stroke-width="2.5"/>${points.map(([x,y],i)=>`<g><path d="M${x} ${y+8}V145" stroke="#ffffff" opacity=".12" stroke-dasharray="2 4"/><circle cx="${x}" cy="${y}" r="9" fill="${i===0||completed.has(challenges[i-1].id)?'#f35a27':'#304c3f'}" stroke="${i===0||completed.has(challenges[i-1].id)?'#f35a27':'#bed09c'}" stroke-width="2"/><text x="${x}" y="${y+3}" fill="white" text-anchor="middle" font-size="9" font-family="sans-serif">${i===0?'✓':i}</text></g>`).join('')}</svg>`}
function openDetail(id){currentId=id;const content=document.getElementById('dialog-content');if(id==='marriage'){content.innerHTML=`${badge('heart','#e94919')}<p class="eyebrow">BADGE 01 · EARNED ON YOUR WEDDING DAY</p><h2>Officially a team.</h2><p>One very important “yes”. A lifetime of adventures ahead.</p><div class="reward"><h3>Your first achievement is already yours.</h3><p>This badge is for choosing each other. The next seven are for all the little things you’ll do together.</p></div><button class="primary" id="dialog-done">Let the adventures begin</button>`;document.getElementById('dialog-done').onclick=()=>dialog.close()}else{const c=challenges.find(c=>c.id===id);if(!c)return;const earned=completed.has(id);content.innerHTML=`${badge(c.icon,c.color)}<p class="eyebrow">${c.category} · ${earned?'BADGE EARNED':'YOUR NEXT ADVENTURE?'}</p><h2>${c.name}</h2><p>${c.mission}</p><div class="reward"><h3>${earned?'✓ Unlocked · A little love from your crew':'Your reward, waiting at the finish'}</h3><p>${earned?c.reward:'A video message from your people, a new badge for your collection, and a little extra.'}</p>${earned?`<p style="margin-top:12px">${c.extra}</p><div id="media-slot"></div><p class="pending">${c.video||c.gift?'':'Your crew’s video and gift details haven’t been added yet. Your badge is yours to keep.'}</p>`:''}</div><button class="primary" id="complete">${earned?'Keep exploring':'We did it · Unlock our badge'}</button>${earned?'<button class="undo" id="undo">Marked complete by mistake? Undo</button>':''}`;if(earned){const slot=document.getElementById('media-slot');if(c.video){const v=document.createElement('video');v.src=c.video;v.controls=true;v.style.width='100%';slot.append(v)}if(c.gift){const a=document.createElement('a');a.href=c.gift;a.textContent='Open your extra surprise ↗';a.target='_blank';a.rel='noopener';slot.append(a)}}document.getElementById('complete').onclick=()=>{if(earned)dialog.close();else{completed.add(id);persist();render();openDetail(id);toast('A new memory. A new badge. Nicely done, team.')}};if(earned)document.getElementById('undo').onclick=()=>{completed.delete(id);persist();render();openDetail(id)}}if(!dialog.open)dialog.showModal()}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3500)}
document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.getElementById('view-marriage').onclick=()=>openDetail('marriage');render();if(!storageAvailable)document.querySelector('footer>span:last-child').textContent='Progress lasts for this visit only.';
if(document.modelContext?.registerTool){const context=document.modelContext;for(const tool of [{name:'list_challenges',description:'Read wedding challenges and completion state on this device.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({challenges:challenges.map(c=>({id:c.id,name:c.name,completed:completed.has(c.id)})),marriageBadgeEarned:true})},{name:'open_challenge',description:'Open a challenge description without completing it.',inputSchema:{type:'object',properties:{id:{type:'string',enum:['marriage',...challenges.map(c=>c.id)]}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.id!=='string'||!['marriage',...challenges.map(c=>c.id)].includes(input.id))throw new Error('Unknown challenge');openDetail(input.id);return{opened:input.id}}}]){try{Promise.resolve(context.registerTool(tool)).catch(()=>{})}catch{}}}
